// burst_ctl.sv: the burst sequencer of the shell window (course task): runs `TOTAL` clocks after GO; `en` is MASK[cnt] for the first 32 of them; `idx` counts the enables so far.
module burst_ctl #(
    parameter int TOTAL = 64
) (
    input  logic        clk,
    input  logic        rst,
    input  logic        go,
    input  logic [31:0] mask,
    output logic        active,
    output logic [6:0]  cnt,
    output logic        en,
    output logic [5:0]  idx,
    output logic        done
);
    assign en = active && (cnt < 7'd32) && mask[cnt[4:0]];
    always_ff @(posedge clk) begin
        if (rst) begin
            active <= 1'b0; cnt <= '0; idx <= '0; done <= 1'b0;
        end else if (go) begin
            active <= 1'b1; cnt <= '0; idx <= '0; done <= 1'b0;
        end else if (active) begin
            cnt <= cnt + 1'b1;
            if (en) idx <= idx + 1'b1;
            if (cnt == TOTAL - 1) begin active <= 1'b0; done <= 1'b1; end
        end
    end
endmodule

// c11_nco_mixer_regs.sv: the shell window of course task c11_nco_mixer (burst of samples, result pairs, a valid record).
module c11_nco_mixer_regs (
    input  logic        clk,
    input  logic        rst,
    output logic [15:0] led,
    input  logic [6:0]  win_addr,
    input  logic        win_wr,
    input  logic        win_rd,
    input  logic [31:0] win_wdata,
    output logic [31:0] win_rdata
);
    localparam int LAT = 1;
    logic [31:0] mask_r, vmask;
    logic [15:0] fw_r;
    logic [11:0] samp [16];
    logic [27:0] outq [16];
    logic [5:0]  nout;
    logic        go, active, en, done, ov;
    logic [6:0]  cnt;
    logic [5:0]  idx;
    logic signed [11:0] io, qo;

    assign led = 16'd0;

    burst_ctl u_burst (.clk(clk), .rst(rst), .go(go), .mask(mask_r), .active(active), .cnt(cnt), .en(en), .idx(idx), .done(done));
    nco_mixer u_core (.clk(clk), .rst_n(!rst), .en(en), .fw(fw_r), .x(samp[idx[3:0]]), .out_valid(ov), .i_out(io), .q_out(qo));

    always_ff @(posedge clk) begin
        go <= 1'b0;
        if (go) begin nout <= '0; vmask <= '0; end
        else if (active && ov) begin
            if (nout < 6'd16) outq[nout[3:0]] <= {4'd0, qo[11:0], 4'd0, io[11:0]};
            nout <= nout + 1'b1;
            if (cnt >= LAT && cnt - LAT < 7'd32) vmask[cnt - LAT] <= 1'b1;
        end
        if (win_wr) begin
            if (win_addr == 7'h00) mask_r <= win_wdata;
            if (win_addr == 7'h01) go <= 1'b1;
            if (win_addr == 7'h05) fw_r <= win_wdata[15:0];
            if (win_addr[6:4] == 3'd1) samp[win_addr[3:0]] <= win_wdata[11:0];
        end
        win_rdata <= 32'd0;
        if (win_rd) begin
            if (win_addr == 7'h00) win_rdata <= mask_r;
            if (win_addr == 7'h02) win_rdata <= {31'd0, done};
            if (win_addr == 7'h03) win_rdata <= {26'd0, nout};
            if (win_addr == 7'h04) win_rdata <= vmask;
            if (win_addr == 7'h05) win_rdata <= {16'd0, fw_r};
            if (win_addr[6:4] == 3'd1) win_rdata <= {20'd0, samp[win_addr[3:0]]};
            if (win_addr[6:4] == 3'd2) win_rdata <= (6'(win_addr[3:0]) < nout) ? {4'd0, outq[win_addr[3:0]]} : 32'd0;
        end
        if (rst) begin
            mask_r <= '0; vmask <= '0; fw_r <= '0; nout <= '0; go <= 1'b0; win_rdata <= 32'd0;
            for (int i = 0; i < 16; i++) begin samp[i] <= '0; outq[i] <= '0; end
        end
    end
endmodule

// c11_nco_mixer_top.sv: board top (Nexys A7-100T, master-XDC port names), test shell DESIGN_ID "NCOM".
// Reference design for course task c11_nco_mixer; the shell window is wired to c11_nco_mixer_regs.
module c11_nco_mixer_top #(
    parameter int          CLKS_PER_BIT   = 868,
    parameter int          TIMEOUT_CYCLES = 100_000,
    parameter logic [31:0] BUILD_STAMP    = 32'h0
) (
    input  logic        CLK100MHZ,
    input  logic        CPU_RESETN,
    output logic [15:0] LED,
    input  logic        UART_TXD_IN,
    output logic        UART_RXD_OUT
);
    logic        clk, rst, win_wr, win_rd;
    logic [6:0]  win_addr;
    logic [31:0] win_wdata, win_rdata;

    assign clk = CLK100MHZ;
    reset_sync u_rst (.clk(clk), .rst_n_async(CPU_RESETN), .rst(rst));

    fpga_shell #(.CLKS_PER_BIT(CLKS_PER_BIT), .TIMEOUT_CYCLES(TIMEOUT_CYCLES),
                 .DESIGN_ID(32'h4e434f4d), .BUILD_STAMP(BUILD_STAMP)) u_shell (
        .clk(clk), .rst(rst), .uart_rx(UART_TXD_IN), .uart_tx(UART_RXD_OUT),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));

    c11_nco_mixer_regs u_regs (
        .clk(clk), .rst(rst), .led(LED),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));
endmodule

// Part 11 lesson 3 solution: an NCO and a complex mixer (digital down-conversion step).
module nco_mixer #(
    parameter int AW = 16,
    parameter int LA = 8,
    parameter int XW = 12
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 en,
    input  logic [AW-1:0]        fw,
    input  logic signed [XW-1:0] x,
    output logic                 out_valid,
    output logic signed [XW-1:0] i_out,
    output logic signed [XW-1:0] q_out
);
    localparam int CW = 16;
    logic signed [CW-1:0] lut [2**LA];
    logic [AW-1:0] acc;

    initial begin
        for (int i = 0; i < 2**LA; i++)
            lut[i] = CW'($rtoi($floor(16383.0 * $sin(6.283185307179586 * i / (2.0**LA)) + 0.5)));
    end

    wire [LA-1:0] idx = acc[AW-1 -: LA];
    wire signed [CW-1:0] s = lut[idx];
    wire signed [CW-1:0] c = lut[idx + LA'(2**(LA-2))];
    wire signed [XW+CW-1:0] pi = x * c;
    wire signed [XW+CW-1:0] pq = x * (-s);

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            acc <= '0; out_valid <= 1'b0; i_out <= '0; q_out <= '0;
        end else begin
            out_valid <= en;
            if (en) begin
                acc   <= acc + fw;
                i_out <= XW'(pi >>> 14);
                q_out <= XW'(pq >>> 14);
            end
        end
    end
endmodule
